script='''const q=new URLSearchParams(location.search),nonce=q.get('recording');if(!/^[0-9a-f]{32}$/.test(nonce))throw Error('Fresh owned nonce required');document.title='Parent resize history · original isolation '+nonce;
const frame=document.getElementById('original'),wait=ms=>new Promise(r=>setTimeout(r,ms));if(document.readyState!=='complete')await new Promise(r=>window.addEventListener('load',r,{once:true}));if(!frame.contentWindow.location.pathname.endsWith('-inner.html')||frame.contentDocument.readyState!=='complete'||frame.contentWindow.eval('typeof initial')!=='function')throw Error('Actual unchanged inner source not loaded');const w=frame.contentWindow,d=frame.contentDocument;
const box=e=>{if(!e)return null;const r=e.getBoundingClientRect();return{x:r.x,y:r.y,width:r.width,height:r.height}};
const text=e=>{const st=w.getComputedStyle(e),lines=[];const walker=d.createTreeWalker(e,NodeFilter.SHOW_TEXT);let node;while(node=walker.nextNode())for(let i=0;i<node.textContent.length;i++){const range=d.createRange();range.setStart(node,i);range.setEnd(node,i+1);const r=range.getBoundingClientRect();if(!r.width&&!r.height)continue;let line=lines.find(l=>Math.abs(l.y-r.y)<.01);if(!line){line={x:r.x,y:r.y,right:r.right,height:r.height,text:''};lines.push(line)}line.x=Math.min(line.x,r.x);line.right=Math.max(line.right,r.right);line.text+=node.textContent[i]}return{text:e.textContent,box:box(e),font:st.font,lineHeight:st.lineHeight,computedWidth:st.width,lines:lines.map(l=>({...l,width:l.right-l.x}))}};
const paths=[[1280,960],[1280,1100,960],[1280,1180,960],[1280,1181,960],[1280,1179,960],[1280,960,1100,960]],rows=[];
for(const widths of paths){frame.width=1280;await new Promise(r=>w.requestAnimationFrame(()=>w.requestAnimationFrame(r)));w.eval('clearInterval(timer);lang="ko";state=initial();state.connected=true;go("review");');await d.fonts.ready;await Promise.all([...d.querySelectorAll('.page')].flatMap(p=>p.getAnimations().map(a=>a.finished.catch(()=>{}))));await wait(80);const initialPage=d.querySelector('.page'),initialHeading=d.getElementById('screen-title'),initialSummary=d.querySelector('.summary-list'),states=[];
for(const width of widths){frame.width=width;await d.fonts.ready;await new Promise(r=>w.requestAnimationFrame(()=>w.requestAnimationFrame(()=>w.requestAnimationFrame(r))));await wait(100);const main=d.getElementById('main'),page=d.querySelector('.page'),st=w.getComputedStyle(main),summary=d.querySelector('.summary-list'),rect=main.getBoundingClientRect();const border=parseFloat(st.borderLeftWidth)+parseFloat(st.borderRightWidth);states.push({width:w.innerWidth,height:w.innerHeight,dpr:w.devicePixelRatio,fontReady:d.fonts.status,pageSame:page===initialPage,headingSame:d.getElementById('screen-title')===initialHeading,summarySame:summary===initialSummary,pageAnimations:page.getAnimations().filter(a=>a.playState==='running').length,media:{small:w.matchMedia('(max-width:1180px)').matches,compact:w.matchMedia('(max-width:1100px)').matches},main:{box:box(main),clientWidth:main.clientWidth,clientHeight:main.clientHeight,offsetWidth:main.offsetWidth,offsetHeight:main.offsetHeight,scrollWidth:main.scrollWidth,scrollHeight:main.scrollHeight,scrollLeft:main.scrollLeft,scrollTop:main.scrollTop,gutter:rect.width-border-main.clientWidth,padding:st.padding,overflowX:st.overflowX,overflowY:st.overflowY},page:box(page),heading:box(d.querySelector('.page-heading')),summary:box(summary),choice:box(d.querySelector('[data-flag=stopped]')),document:{clientWidth:d.documentElement.clientWidth,clientHeight:d.documentElement.clientHeight,scrollWidth:d.documentElement.scrollWidth,scrollHeight:d.documentElement.scrollHeight},items:[...summary.children].map(row=>({row:box(row),label:text(row.children[0]),value:text(row.children[1])})),publicState:w.eval('({screen:state.screen,connected:state.connected,selected:[...state.selected],tables:[...state.tables],stopped:state.stopped,run:state.run})')});}rows.push({id:widths.join('-'),widths,states});}
const result={scope:'parent-resize-history6',recording:nonce,dpr:w.devicePixelRatio,originalHashes:HASHES,rows};const response=await fetch('/evidence/connection-pageintegrationviewporthistory-windows-source.json',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(result)});if(!response.ok)throw Error('Owned evidence POST '+response.status);document.getElementById('result').textContent='Recorded six original histories';document.title='Parent resize history recorded · original isolation '+nonce;
'''.replace('HASHES',json.dumps(hashes))
